const ProjectCard = ({ title, icon, description, tech, url, color }) => {
  const cardRef = useRef(null);

  const handleMouseMove = (e) => {
    const card = cardRef.current;
    if (!card) return;
    const rect = card.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const centerX = rect.width / 2;
    const centerY = rect.height / 2;
    const rotateX = ((y - centerY) / centerY) * -8;
    const rotateY = ((x - centerX) / centerX) * 8;
    card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) translateZ(10px)`;
  };

  const handleMouseLeave = () => {
    const card = cardRef.current;
    if (!card) return;
    card.style.transform = 'perspective(1000px) rotateX(0) rotateY(0) translateZ(0)';
  };

  return (
    <a
      href={url}
      target="_blank"
      rel="noopener noreferrer"
      className="project-card-link"
    >
      <div
        ref={cardRef}
        className="project-card glass-card"
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
        style={{ '--card-color': color }}
      >
        {/* Glow background */}
        <div className="project-card-glow" style={{ background: `radial-gradient(circle at top left, ${color}18, transparent 60%)` }} />

        {/* Header */}
        <div className="project-card-header">
          <span className="project-card-icon">{icon}</span>
          <span className="project-card-arrow">↗</span>
        </div>

        <h3 className="project-card-title">{title}</h3>
        <p className="project-card-desc">{description}</p>

        <div className="project-card-tech">
          {tech.map((t) => (
            <span key={t} className="tech-badge">{t}</span>
          ))}
        </div>
      </div>
    </a>
  );
};

