// src/components/HeroSection/HeroSection.jsx
import React, { useRef, useEffect, Suspense } from 'react';
import './HeroSection.css';
import { Canvas, useFrame, useThree } from 'react-three-fiber';
import { Stars, MeshDistortMaterial } from '@react-three/drei';
import * as THREE from 'three';
import { gsap } from 'gsap';

/* ---- 3D Sphere ---- */
const AnimatedSphere = () => {
  const meshRef = useRef();
  const { mouse } = useThree();

  useFrame((state) => {
    if (!meshRef.current) return;
    meshRef.current.rotation.x += 0.003;
    meshRef.current.rotation.y += 0.005;
    // Subtle follow mouse
    meshRef.current.position.x = THREE.MathUtils.lerp(
      meshRef.current.position.x,
      mouse.x * 0.5,
      0.05
    );
    meshRef.current.position.y = THREE.MathUtils.lerp(
      meshRef.current.position.y,
      mouse.y * 0.3,
      0.05
    );
  });

  return (
    <mesh ref={meshRef} position={[0, 0, 0]}>
      <icosahedronGeometry args={[2.2, 4]} />
      <MeshDistortMaterial
        color="#FFD700"
        attach="material"
        distort={0.3}
        speed={2}
        wireframe={true}
        opacity={0.35}
        transparent={true}
      />
    </mesh>
  );
};

/* ---- Floating Ring ---- */
const FloatingRing = () => {
  const ringRef = useRef();

  useFrame((state) => {
    if (!ringRef.current) return;
    ringRef.current.rotation.x = Math.sin(state.clock.elapsedTime * 0.4) * 0.3;
    ringRef.current.rotation.z += 0.008;
  });

  return (
    <mesh ref={ringRef} position={[0, 0, 0]}>
      <torusGeometry args={[3.2, 0.02, 16, 100]} />
      <meshStandardMaterial
        color="#FFD700"
        emissive="#FFD700"
        emissiveIntensity={0.5}
        opacity={0.4}
        transparent={true}
      />
    </mesh>
  );
};

/* ---- Scene ---- */
const Scene = () => (
  <>
    <ambientLight intensity={0.3} />
    <pointLight position={[10, 10, 10]} intensity={1} color="#FFD700" />
    <pointLight position={[-10, -10, -10]} intensity={0.5} color="#FFA000" />
    <Stars
      radius={100}
      depth={50}
      count={5000}
      factor={4}
      saturation={0}
      fade
      speed={0.5}
    />
    <AnimatedSphere />
    <FloatingRing />
  </>
);

/* ---- HeroSection ---- */
const HeroSection = () => {
  const textRef = useRef();
  const subRef = useRef();
  const btnRef = useRef();

  useEffect(() => {
    const tl = gsap.timeline({ delay: 0.3 });
    tl.fromTo(
      '.hero-title',
      { opacity: 0, y: 40 },
      { opacity: 1, y: 0, duration: 0.9, ease: 'power3.out' }
    )
      .fromTo(
        '.hero-subtitle',
        { opacity: 0, y: 20 },
        { opacity: 1, y: 0, duration: 0.7, ease: 'power3.out' },
        '-=0.4'
      )
      .fromTo(
        '.hero-desc',
        { opacity: 0, y: 20 },
        { opacity: 1, y: 0, duration: 0.7, ease: 'power3.out' },
        '-=0.3'
      )
      .fromTo(
        '.hero-btns',
        { opacity: 0, y: 20 },
        { opacity: 1, y: 0, duration: 0.6, ease: 'power3.out' },
        '-=0.3'
      );
  }, []);

  return (
    <section id="inicio" className="hero-section">
      {/* Three.js Canvas Background */}
      <div className="hero-canvas">
        <Canvas
          camera={{ position: [0, 0, 8], fov: 60 }}
          gl={{ alpha: true, antialias: true }}
          style={{ background: 'transparent' }}
        >
          <Suspense fallback={null}>
            <Scene />
          </Suspense>
        </Canvas>
      </div>

      {/* Gradient overlay */}
      <div className="hero-overlay" />

      {/* Content */}
      <div className="hero-content container">
        <div className="hero-avatar-wrap">
          <img
            src="https://i.ibb.co/nNVG6qff/peeps-avatar-alpha.png"
            alt="Sebastián Sandoval"
            className="hero-avatar"
          />
          <div className="hero-avatar-ring" />
        </div>

        <p className="hero-eyebrow">Analista Programador Computacional</p>

        <h1 className="hero-title" ref={textRef}>
          Sebastián<br />
          <span className="hero-title-highlight">Sandoval Rojas</span>
        </h1>

        <p className="hero-subtitle" ref={subRef}>
          Full Stack Developer
        </p>

        <p className="hero-desc">
          Transformando ideas en soluciones tecnológicas simples,<br className="hide-mobile" />
          eficientes y escalables.
        </p>

        <div className="hero-btns" ref={btnRef}>
          <a href="#proyectos" className="btn-custom">Ver Proyectos</a>
          <a href="#contacto" className="btn-outline">Contactarme</a>
          <a
            href={process.env.PUBLIC_URL + '/assets/CVSEBASTIANSANDOVAL.pdf'}
            download
            className="btn-outline"
          >
            Descargar CV
          </a>
        </div>

        {/* Scroll hint */}
        <div className="hero-scroll-hint">
          <div className="hero-scroll-mouse">
            <div className="hero-scroll-wheel" />
          </div>
          <span>Scroll</span>
        </div>
      </div>
    </section>
  );
};

export default HeroSection;