import React from 'react';
import './SkillsSection.css';

const skillCategories = [
  {
    id: 'frontend',
    icon: '🖥️',
    title: 'Frontend',
    color: '#FFD700',
    skills: ['HTML', 'CSS', 'JavaScript', 'Bootstrap', 'React.js'],
  },
  {
    id: 'backend',
    icon: '⚙️',
    title: 'Backend',
    color: '#FFA000',
    skills: ['C#', 'Python', 'PHP', 'Java'],
  },
  {
    id: 'database',
    icon: '🗄️',
    title: 'Bases de Datos',
    color: '#FFD700',
    skills: ['MySQL', 'Oracle 11g', 'SQL'],
  },
  {
    id: 'otros',
    icon: '🚀',
    title: 'DevOps & Otros',
    color: '#FFA000',
    skills: ['Docker', 'AWS', 'WPF', 'Arquitectura MVC'],
  },
];

const SkillCard = ({ icon, title, color, skills, delay }) => (
  <div
    className="skill-card glass-card"
    data-aos="fade-up"
    data-aos-delay={delay}
    style={{ '--card-accent': color }}
  >
    <div className="skill-card-header">
      <span className="skill-card-icon">{icon}</span>
      <h4 className="skill-card-title" style={{ color }}>{title}</h4>
    </div>
    <div className="skill-card-divider" style={{ background: `linear-gradient(90deg, ${color}, transparent)` }} />
    <ul className="skill-list">
      {skills.map((skill, i) => (
        <li key={skill} className="skill-item" style={{ animationDelay: `${i * 0.08}s` }}>
          <span className="skill-dot" style={{ background: color, boxShadow: `0 0 6px ${color}` }} />
          {skill}
        </li>
      ))}
    </ul>
  </div>
);

const SkillsSection = () => {
  return (
    <section
      id="habilidades"
      className="skills-section section-padding"
    >
      <div className="container">
        <h2 className="section-title" data-aos="fade-up">Habilidades Técnicas</h2>
        <div className="skills-grid">
          {skillCategories.map((cat, i) => (
            <SkillCard key={cat.id} {...cat} delay={i * 100} />
          ))}
        </div>
      </div>
    </section>
  );
};

export default SkillsSection;