// src/components/Footer/Footer.jsx
import React, { useState } from 'react';
import './Footer.css';

const Footer = () => {
  const [launching, setLaunching] = useState(false);

  const handleClick = (e) => {
    e.preventDefault();
    if (launching) return;
    setLaunching(true);
    setTimeout(() => {
      setLaunching(false);
      document.getElementById('inicio')?.scrollIntoView({ behavior: 'smooth' });
    }, 1200);
  };

  return (
    <footer className="footer">
      <button
        className={`rocket-btn ${launching ? 'launching' : ''}`}
        onClick={handleClick}
        title="Volver arriba"
        aria-label="Volver al inicio"
      >
        {/* Launch pad */}
        <div className="launchpad" />

        {/* Smoke particles */}
        <div className="smoke">
          {[...Array(8)].map((_, i) => (
            <span key={i} className={`smoke-particle sp-${i}`} />
          ))}
        </div>

        {/* Rocket SVG */}
        <svg
          className="rocket-svg"
          viewBox="0 0 60 100"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          {/* Body */}
          <path
            d="M30 5 C18 18 14 40 14 58 L46 58 C46 40 42 18 30 5Z"
            fill="url(#bodyGrad)"
          />
          {/* Nose cone highlight */}
          <path
            d="M30 5 C26 16 24 30 24 44 L30 44 L30 5Z"
            fill="rgba(255,255,255,0.15)"
          />
          {/* Window */}
          <circle cx="30" cy="40" r="6" fill="url(#windowGrad)" />
          <circle cx="30" cy="40" r="4" fill="url(#windowInner)" />
          <circle cx="28" cy="38" r="1.2" fill="rgba(255,255,255,0.7)" />
          {/* Left fin */}
          <path d="M14 58 L4 72 L14 68 Z" fill="url(#finGrad)" />
          {/* Right fin */}
          <path d="M46 58 L56 72 L46 68 Z" fill="url(#finGrad)" />
          {/* Nozzle */}
          <rect x="24" y="58" width="12" height="6" rx="2" fill="#888" />

          {/* Flame outer */}
          <path
            className="flame flame-outer"
            d="M20 64 Q22 80 30 90 Q38 80 40 64 Z"
            fill="url(#flameOuter)"
          />
          {/* Flame inner */}
          <path
            className="flame flame-inner"
            d="M24 64 Q26 76 30 84 Q34 76 36 64 Z"
            fill="url(#flameInner)"
          />
          {/* Flame core */}
          <path
            className="flame flame-core"
            d="M27 64 Q28 72 30 78 Q32 72 33 64 Z"
            fill="white"
          />

          <defs>
            <linearGradient id="bodyGrad" x1="14" y1="5" x2="46" y2="60" gradientUnits="userSpaceOnUse">
              <stop offset="0%" stopColor="#e8e8f0" />
              <stop offset="100%" stopColor="#8888aa" />
            </linearGradient>
            <radialGradient id="windowGrad" cx="50%" cy="50%">
              <stop offset="0%" stopColor="#00d4ff" />
              <stop offset="100%" stopColor="#0044aa" />
            </radialGradient>
            <radialGradient id="windowInner" cx="40%" cy="40%">
              <stop offset="0%" stopColor="#88eeff" />
              <stop offset="100%" stopColor="#0066cc" />
            </radialGradient>
            <linearGradient id="finGrad" x1="0" y1="58" x2="0" y2="72" gradientUnits="userSpaceOnUse">
              <stop offset="0%" stopColor="#cc3333" />
              <stop offset="100%" stopColor="#881111" />
            </linearGradient>
            <linearGradient id="flameOuter" x1="30" y1="64" x2="30" y2="90" gradientUnits="userSpaceOnUse">
              <stop offset="0%" stopColor="#FF6600" />
              <stop offset="60%" stopColor="#FF3300" stopOpacity="0.8" />
              <stop offset="100%" stopColor="#FF0000" stopOpacity="0" />
            </linearGradient>
            <linearGradient id="flameInner" x1="30" y1="64" x2="30" y2="84" gradientUnits="userSpaceOnUse">
              <stop offset="0%" stopColor="#FFAA00" />
              <stop offset="100%" stopColor="#FF6600" stopOpacity="0" />
            </linearGradient>
          </defs>
        </svg>
      </button>
    </footer>
  );
};

export default Footer;